content.com/u/4107631?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/mdsumner\",\"html_url\":\"https://github.com/mdsumner\",\"followers_url\":\"https://api.github.com/users/mdsumner/followers\",\"following_url\":\"https://api.github.com/users/mdsumner/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/mdsumner/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/mdsumner/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/mdsumner/subscriptions\",\"organizations_url\":\"https://api.github.com/users/mdsumner/orgs\",\"repos_url\":\"https://api.github.com/users/mdsumner/repos\",\"events_url\":\"https://api.github.com/users/mdsumner/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/mdsumner/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"labels\":[],\"state\":\"closed\",\"locked\":false,\"assignees\":[],\"milestone\":null,\"comments\":1,\"created_at\":\"2019-01-15T23:21:19Z\",\"updated_at\":\"2019-03-20T03:56:52Z\",\"closed_at\":\"2019-03-20T03:56:52Z\",\"assignee\":null,\"author_association\":\"MEMBER\",\"issue_field_values\":[],\"type\":null,\"active_lock_reason\":null,\"sub_issues_summary\":{\"total\":0,\"completed\":0,\"percent_completed\":0},\"issue_dependencies_summary\":{\"blocked_by\":0,\"total_blocked_by\":0,\"blocking\":0,\"total_blocking\":0},\"body\":\"@dblodgett-usgs  I see a problem in this test **test-gridmapping-prj** on Windows, but not Linux. \\r\\n\\r\\nIt comes  down to this including \\\"semi_minor_axis\\\" on Windows but \\\"inverse_flattening\\\" on Linux. \\r\\n\\r\\n```R\\r\\np <- \\\"+proj=lcc +lat_1=30 +lat_2=60 +x_0=0 +y_0=0 +units=m +lat_0=40.0000076294 +lon_0=-97 +a=6370000 +b=6370000 +pm=0 +no_defs\\\"\\r\\nnc_prj_to_gridmapping(p)\\r\\n```\\r\\n\\r\\nLINUX:\\r\\n```\\r\\n# A tibble: 9 x 2\\r\\n  name                          value    \\r\\n  <chr>                         <list>   \\r\\n1 grid_mapping_name             <chr [1]>\\r\\n2 standard_parallel             <dbl [2]>\\r\\n3 false_easting                 <dbl [1]>\\r\\n4 false_northing                <dbl [1]>\\r\\n5 latitude_of_projection_origin <dbl [1]>\\r\\n6 longitude_of_central_meridian <dbl [1]>\\r\\n7 semi_major_axis               <dbl [1]>\\r\\n8 inverse_flattening            <dbl [1]>\\r\\n9 longitude_of_prime_meridian   <dbl [1]>\\r\\n```\\r\\n\\r\\nWINDOWS: \\r\\n\\r\\n```\\r\\n# A tibble: 9 x 2\\r\\n  name                          value    \\r\\n  <chr>                         <list>   \\r\\n1 grid_mapping_name             <chr [1]>\\r\\n2 standard_parallel             <dbl [2]>\\r\\n3 false_easting                 <dbl [1]>\\r\\n4 false_northing                <dbl [1]>\\r\\n5 latitude_of_projection_origin <dbl [1]>\\r\\n6 longitude_of_central_meridian <dbl [1]>\\r\\n7 semi_major_axis               <dbl [1]>\\r\\n8 semi_minor_axis               <dbl [1]>\\r\\n9 longitude_of_prime_meridian   <dbl [1]>\\r\\n```\\r\\n\\r\\nBut I wasn't able to pin it down any further yet (I did make some changes in the the `GGFP` methods to make the return value explicit). \\r\\n\",\"closed_by\":{\"login\":\"mdsumner\",\"id\":4107631,\"node_id\":\"MDQ6VXNlcjQxMDc2MzE=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/4107631?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/mdsumner\",\"html_url\":\"https://github.com/mdsumner\",\"followers_url\":\"https://api.github.com/users/mdsumner/followers\",\"following_url\":\"https://api.github.com/users/mdsumner/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/mdsumner/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/mdsumner/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/mdsumner/subscriptions\",\"organizations_url\":\"https://api.github.com/users/mdsumner/orgs\",\"repos_url\":\"https://api.github.com/users/mdsumner/repos\",\"events_url\":\"https://api.github.com/users/mdsumner/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/mdsumner/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"reactions\":{\"url\":\"ghrepos/hypertidy/ncmeta/issues/24/reactions\",\"total_count\":0,\"+1\":0,\"-1\":0,\"laugh\":0,\"hooray\":0,\"confused\":0,\"heart\":0,\"rocket\":0,\"eyes\":0},\"timeline_url\":\"ghrepos/hypertidy/ncmeta/issues/24/timeline\",\"performed_via_github_app\":null,\"state_reason\":\"completed\",\"pinned_comment\":null},{\"url\":\"ghrepos/hypertidy/ncmeta/issues/23\",\"repository_url\":\"ghrepos/hypertidy/ncmeta\",\"labels_url\":\"ghrepos/hypertidy/ncmeta/issues/23/labels{/name}\",\"comments_url\":\"ghrepos/hypertidy/ncmeta/issues/23/comments\",\"events_url\":\"ghrepos/hypertidy/ncmeta/issues/23/events\",\"html_url\":\"https://github.com/hypertidy/ncmeta/issues/23\",\"id\":397894230,\"node_id\":\"MDU6SXNzdWUzOTc4OTQyMzA=\",\"number\":23,\"title\":\"nc_axis row order\",\"user\":{\"login\":\"dblodgett-usgs\",\"id\":1492803,\"node_id\":\"MDQ6VXNlcjE0OTI4MDM=\",\"avatar_url\":\"https://avatars.githubusercontent.com/u/1492803?v=4\",\"gravatar_id\":\"\",\"url\":\"https://api.github.com/users/dblodgett-usgs\",\"html_url\":\"https://github.com/dblodgett-usgs\",\"followers_url\":\"https://api.github.com/users/dblodgett-usgs/followers\",\"following_url\":\"https://api.github.com/users/dblodgett-usgs/following{/other_user}\",\"gists_url\":\"https://api.github.com/users/dblodgett-usgs/gists{/gist_id}\",\"starred_url\":\"https://api.github.com/users/dblodgett-usgs/starred{/owner}{/repo}\",\"subscriptions_url\":\"https://api.github.com/users/dblodgett-usgs/subscriptions\",\"organizations_url\":\"https://api.github.com/users/dblodgett-usgs/orgs\",\"repos_url\":\"https://api.github.com/users/dblodgett-usgs/repos\",\"events_url\":\"https://api.github.com/users/dblodgett-usgs/events{/privacy}\",\"received_events_url\":\"https://api.github.com/users/dblodgett-usgs/received_events\",\"type\":\"User\",\"user_view_type\":\"public\",\"site_admin\":false},\"labels\":[],\"state\":\"open\",\"locked\":false,\"assignees\":[],\"milestone\":null,\"comments\":4,\"created_at\":\"2019-01-10T15:53:36Z\",\"updated_at\":\"2019-04-30T01:54:53Z\",\"closed_at\":null,\"assignee\":null,\"author_association\":\"CONTRIBUTOR\",\"issue_field_values\":[],\"type\":null,\"active_lock_reason\":null,\"sub_issues_summary\":{\"total\":0,\"completed\":0,\"percent_completed\":0},\"issue_dependencies_summary\":{\"blocked_by\":0,\"total_blocked_by\":0,\"blocking\":0,\"total_blocking\":0},\"body\":\"Based on this: https://github.com/hypertidy/ncmeta/blob/master/R/nc_axes.R#L46 the row order of the response from nc_axis is in the order of the `RNetCDF::var.inq.nc()$dimid` vector. Is this by design? I ask because that `$dimid` for a variable determines what order you put dimensions in start and count for `RNetCDF::var.get.nc()` and it's pretty important to get right!! \\r\\n\\r\\nI wonder if adding a list column to the nc_var() response that would contain the $dimid vector would be safer? The fact that the row order corresponds dimension order is being used here: https://github.com/r-spatial/stars/blob/master/R/ncdf.R#L58 already so at the least there should be some testing to make sure that the row order doesn't get mucked up?\\r\\n\\r\\n```r\\r\\nvar <- \\\"ppt\\\"\\r\\nh_nc <- RNetCDF::open.nc(\\\"https://cida.usgs.gov/thredds/dodsC/prism_v2\\\")\\r\\n\\r\\ndplyr::filter(nc_axes(h), variable == var)$dimension\\r\\n# [1] 1 0 3\\r\\n\\r\\nRNetCDF::var.inq.nc(h_nc, var)$dimids\\r\\n# [1] 1 0 3\\r\\n```\",\"closed_by\":null,\"reactions\":{\"url\":\"ghrepos/hypertidy/ncmeta/issues/23/reactions\",\"total_count\":0,\"+1\":0,\"-1\":0,\"laugh\":0,\"hooray\":0,\"confused\":0,\"heart\":0,\"rocket\":0,\"eyes\":0},\"timeline_url\":\"ghrepos/hypertidy/ncmeta/issues/23/timeline\",\"performed_via_github_app\":null,\"state_reason\":null,\"pinned_comment\":null},{\"url\":\"ghrepos/hypertidy/ncmeta/issues/22\",\